using Bancoficticio.Transfers.Domain.Model;
using Bancoficticio.Transfers.Domain.Port;
using Bancoficticio.Transfers.Infrastructure;

namespace Bancoficticio.Transfers.Adapters.Out.Sql;

/// <summary>ADO.NET adapter of the AccountRepository port (table cuentas).</summary>
public sealed class SqlAccountRepository(Db db) : AccountRepository
{
    public Cuenta? FindByNumber(string? cuenta)
    {
        using var command = db.Command(
            "SELECT cta_numero, cta_estado, cta_saldo FROM cuentas WHERE cta_numero = @cuenta");
        command.Parameters.AddWithValue("@cuenta", (object?)cuenta ?? DBNull.Value);
        using var reader = command.ExecuteReader();
        if (!reader.Read())
        {
            return null;
        }

        return new Cuenta(
            reader.IsDBNull(0) ? null : reader.GetString(0),
            reader.IsDBNull(1) ? null : reader.GetString(1),
            reader.IsDBNull(2) ? null : reader.GetDecimal(2));
    }

    public bool ExistsActive(string? cuenta)
    {
        using var command = db.Command(
            "SELECT COUNT(*) FROM cuentas WHERE cta_numero = @cuenta AND cta_estado = 'A'");
        command.Parameters.AddWithValue("@cuenta", (object?)cuenta ?? DBNull.Value);
        var result = command.ExecuteScalar();
        return result != null && result != DBNull.Value && Convert.ToInt32(result) > 0;
    }

    public int Debit(string? cuenta, decimal? valor)
    {
        using var command = db.Command(
            "UPDATE cuentas SET cta_saldo = cta_saldo - @valor WHERE cta_numero = @cuenta");
        command.Parameters.AddWithValue("@valor", (object?)valor ?? DBNull.Value);
        command.Parameters.AddWithValue("@cuenta", (object?)cuenta ?? DBNull.Value);
        return command.ExecuteNonQuery();
    }

    public int Credit(string? cuenta, decimal? valor)
    {
        using var command = db.Command(
            "UPDATE cuentas SET cta_saldo = cta_saldo + @valor WHERE cta_numero = @cuenta");
        command.Parameters.AddWithValue("@valor", (object?)valor ?? DBNull.Value);
        command.Parameters.AddWithValue("@cuenta", (object?)cuenta ?? DBNull.Value);
        return command.ExecuteNonQuery();
    }
}
